namespace Causa.Tool

open System
open System.IO
open IndyInitRootCauseInvestigator.Engine
open Causa.Contract

/// DRAFT for owner decision: the causa-storage 1.1.0 conformance fixtures (fixtures/v1.1.0), generated by issuing
/// real commands through the pinned engine (Decide.execute) for every 1.0.0 event, and adding the 1.1.0 revision
/// events and relationship kinds exactly as CONTRACT 1.1.0 section 4.5 says a writer does. Deterministic: fixed clock
/// (step i at start + 4i minutes) and UUIDv5 ids, so a rebuild is byte-identical.
[<RequireQualifiedAccess>]
module V110Fixtures =
    let fixtureNamespace = Uuid.v5 Uuid.urlNamespace "https://github.com/kemiller2002/causa-data/fixtures/v1.1.0"
    let scenarioKey = "j2-analysis"
    let guid kind name = Uuid.v5 fixtureNamespace (scenarioKey + "/" + kind + "/" + name)
    let private id<'T> kind name : Id<'T> = Id.create (guid kind name)
    let start = DateTimeOffset(2026, 11, 6, 12, 0, 0, TimeSpan.Zero)
    let actor = Actor.human "causa-operator"

    type Revision =
        | EvidenceRev of evidence: EvidenceId * label: string * source: string * sourceUrl: string option
        | ObservationRev of observation: ObservationId * original: string * source: string option

    type Step =
        /// An engine command; its events are written as 1.1.0 lines. `kind` replaces the relationship kind of an
        /// EvidenceRelated (the engine is given `Insufficient`, which no gate reads); `revision` follows in the same group.
        | Core of command: Command * kind: string option * revision: Revision option
        /// A ReviseEvidence / ReviseObservation command: one revision event, its own group.
        | Revise of Revision

    let inv = id<InvestigationTag> "investigation" "root"
    let obs0 = id<ObservationTag> "observation" "initial"
    let obsCard = id<ObservationTag> "observation" "card-only"
    let obsCache = id<ObservationTag> "observation" "cache-hit-rate"
    let hGateway = id<HypothesisTag> "hypothesis" "gateway-client"
    let hCache = id<HypothesisTag> "hypothesis" "token-cache"
    let eLog = id<EvidenceTag> "evidence" "gateway-log"
    let eCache = id<EvidenceTag> "evidence" "cache-metrics"
    let eDraft = id<EvidenceTag> "evidence" "draft-capture"
    let rel name = id<RelationshipTag> "relationship" name

    /// Every value a user enters in the J2 journey, kept here so the no-value-dropped test can look for each one.
    let entered =
        {| ObservationCardSource = "ops dashboard, panel 4\nexported 12:05"
           LogLabel = "  Gateway handshake log  "
           LogSource = "gateway access log export"
           LogUrl = "HTTPS://Example.invalid/%7Elogs/502"
           CacheLabel = "Token cache metrics​"
           CacheSource = "metrics export"
           LogLabelRevised = "Gateway TLS handshake log"
           LogSourceRevised = "gateway access log export, 11:50-12:10"
           ObservationRevised = "Checkout p95 latency rose from 300 ms to 2 s after the 11:55 deploy."
           ObservationRevisedSource = "incident ticket INC-0001"
           ConsistentRationale = "A cache eviction fits the timing but does not favour it over the gateway client."
           ReassessRationale = "Reassessed: the handshakes may be a symptom of retries, not the cause."
           DraftLabel = "Draft capture (superseded)" |}

    let steps : Step list =
        let e = entered
        [ Core(StartInvestigation(inv, "Checkout latency regression", obs0, "Checkout p95 latency rose from 300 ms to 2 s after the deploy."), None, None)
          Core(ActivateInvestigation, None, None)
          Core(RecordObservation(obsCard, "The slowdown affects only card payments.", None), None,
               Some(ObservationRev(obsCard, "The slowdown affects only card payments.", Some e.ObservationCardSource)))
          Core(RecordObservation(obsCache, "Cache hit rate fell at 11:58.", Some(start.AddMinutes -2.0)), None, None)
          Core(RecordHypothesis(hGateway, "The new payment-gateway client opens a connection per request.", None), None, None)
          Core(RecordHypothesis(hCache, "The deploy evicted the card-token cache.", Some "Cold cache lookups go to the token service."), None, None)
          Core(AdmitEvidence(eLog, TextInput "Gateway logs show 1,912 new TLS handshakes per minute.", Log, e.LogSource, None), None,
               Some(EvidenceRev(eLog, e.LogLabel, e.LogSource, Some e.LogUrl)))
          Core(AdmitEvidence(eCache, TextInput "Cache metrics show the token cache emptied at 11:58.", Measurement, e.CacheSource, None), None,
               Some(EvidenceRev(eCache, e.CacheLabel, e.CacheSource, None)))
          Core(RelateEvidence(rel "log-supports-gateway", eLog, hGateway, Supports, Some "Per-request handshakes explain the added latency."), None, None)
          Core(RelateEvidence(rel "cache-contradicts-gateway", eCache, hGateway, Contradicts, Some "The cache emptied before the handshake spike."), None, None)
          Core(RelateEvidence(rel "cache-consistent-with-cache", eCache, hCache, Insufficient, Some e.ConsistentRationale), Some "consistentWith", None)
          // S-8 B: a reassessment is a new EvidenceRelated for the same pair; the latest is current.
          Core(RelateEvidence(rel "log-reassessed-gateway", eLog, hGateway, Insufficient, Some e.ReassessRationale), Some "inconclusive", None)
          Revise(EvidenceRev(eLog, e.LogLabelRevised, e.LogSourceRevised, None))
          Revise(ObservationRev(obs0, e.ObservationRevised, Some e.ObservationRevisedSource))
          Core(AdmitEvidence(eDraft, TextInput "Draft capture of the gateway log.", Log, "gateway access log export", None), None,
               Some(EvidenceRev(eDraft, e.DraftLabel, "gateway access log export", None)))
          Core(SupersedeEvidence(eDraft, eLog, "The full export replaces the draft capture."), None, None)
          Core(RecordConclusion(id<ConclusionTag> "conclusion" "first", "The gateway client is the leading explanation so far.", PlausibleExplanation, [],
                                Some "Whether the cache eviction contributes is still open."), None, None) ]

    let private revisionLine (r: Revision) =
        match r with
        | EvidenceRev(eid, label, source, url) ->
            "EvidenceRevised",
            JObj [ "evidenceId", JStr(Uuid.text eid.Value); "label", JStr label; "source", JStr source
                   "sourceUrl", (match url with Some u -> JStr u | None -> JNull) ]
        | ObservationRev(oid, original, source) ->
            "ObservationRevised",
            JObj [ "observationId", JStr(Uuid.text oid.Value); "original", JStr original; "source", (match source with Some s -> JStr s | None -> JNull) ]

    /// The 1.1.0 lines of `steps`, numbered, identified and versioned.
    let linesOf (steps: Step list) : Result<JValue list, string> =
        let invId = inv.Value
        let envelope (n: int64) (corr: Guid) (at: DateTimeOffset) (eventType: string) (payload: JValue) =
            JObj [ "formatVersion", JStr V110.version
                   "eventId", JStr(Uuid.text (Uuid.eventId invId n corr))
                   "investigationId", JStr(Uuid.text invId)
                   "aggregateVersion", JInt n
                   "eventType", JStr eventType
                   "occurredAt", JStr(Timestamp.tryFormat at |> Option.defaultValue "")
                   "actor", JObj [ "actorId", JStr actor.Id; "kind", JStr "human" ]
                   "semanticVersion", JStr V110.version
                   "correlationId", JStr(Uuid.text corr)
                   "payload", payload ]
        steps
        |> List.indexed
        |> List.fold (fun acc (i, step) ->
            acc |> Result.bind (fun (state: Investigation option, lines: JValue list) ->
                let corr = guid "command" (string i)
                let at = start.AddMinutes(4.0 * float i)
                let next () = int64 lines.Length + 1L
                match step with
                | Revise r ->
                    let t, p = revisionLine r
                    Ok(state, lines @ [ envelope (next ()) corr at t p ])
                | Core(command, kind, revision) ->
                    let env = { CommandId = corr; Investigation = inv; ExpectedVersion = state |> Option.map (fun x -> x.Version); Actor = actor; RequestedAt = at; Command = command }
                    match Decide.execute state env with
                    | Error es -> Error($"step {i} was refused: " + String.Join("; ", es |> List.map (fun e -> e.Code + " " + e.Message)))
                    | Ok produced ->
                        let state' = produced |> List.fold (fun s e -> Some(Evolve.apply s e)) state
                        let encoded =
                            produced |> List.mapi (fun j e ->
                                match EventWire.encode e with
                                | Error x -> Error x.Detail
                                | Ok v ->
                                    let payload = V110.field "payload" v |> Option.defaultValue (JObj [])
                                    let payload = match kind with Some k -> V110.setField "kind" (JStr k) payload | None -> payload
                                    Ok(envelope (next () + int64 j) corr at (V110.strField "eventType" v |> Option.defaultValue "") payload))
                        match encoded |> List.tryPick (function Error x -> Some x | _ -> None) with
                        | Some x -> Error($"step {i}: {x}")
                        | None ->
                            let core = encoded |> List.choose (function Ok v -> Some v | _ -> None)
                            let extra =
                                match revision with
                                | Some r -> let t, p = revisionLine r in [ envelope (next () + int64 core.Length) corr at t p ]
                                | None -> []
                            Ok(state', lines @ core @ extra))) (Ok(None, []))
        |> Result.map snd

    let valid () = linesOf steps

    // ---------------- negative fixtures (one targeted rule each) ----------------

    type Negative =
        { Name: string
          Description: string
          Files: InvestigationFiles
          ExpectedErrorCode: string
          ExpectedDomainCode: string option }

    let private bytesOf (lines: JValue list) =
        lines |> traverse (Json.canonical >> Result.mapError (fun (e: string) -> e))
        |> Result.map (fun texts -> Json.strictUtf8.GetBytes(String.Join("", texts |> List.map (fun t -> t + "\n"))))

    let private parseDoc (b: byte[]) =
        Json.decodeUtf8 b |> Result.bind (fun t -> Json.parse (t.Substring(0, t.Length - 1)))

    /// The valid files with `lines` in place of the history: the manifest's counts, times and eventsSha256 follow the
    /// lines, so every stage before the targeted one passes; the snapshot is kept (it is checked after stage 15).
    let private withLines (valid: InvestigationFiles) (lines: JValue list) : Result<InvestigationFiles, string> =
        result {
            let! events = bytesOf lines
            let! manifest = parseDoc valid.Manifest
            let n = int64 lines.Length
            let m =
                manifest
                |> V110.setField "eventsSha256" (JStr(Json.sha256Hex events))
                |> V110.setField "aggregateVersion" (JInt n) |> V110.setField "eventCount" (JInt n)
                |> V110.setField "updatedAt" (V110.field "occurredAt" (List.last lines) |> Option.defaultValue JNull)
            let! mb = Json.fileBytes m
            return { valid with Events = events; Manifest = mb }
        }

    /// Every version string of a file set set to `v` (manifest, snapshot and lines), with the eventsSha256 kept true.
    let private allVersions (v: string) (valid: InvestigationFiles) (lines: JValue list) : Result<InvestigationFiles, string> =
        let set (x: JValue) =
            [ "formatVersion"; "schemaVersion"; "semanticVersion" ]
            |> List.fold (fun acc k -> if (V110.field k acc).IsSome then V110.setField k (JStr v) acc else acc) x
        result {
            let! f = withLines valid (lines |> List.map set)
            let! m = parseDoc f.Manifest
            let! s = parseDoc f.Snapshot
            let! mb = Json.fileBytes (set m)
            let! sb = Json.fileBytes (set s)
            return { f with Manifest = mb; Snapshot = sb }
        }

    let private at (n: int) (f: JValue -> JValue) (lines: JValue list) = lines |> List.mapi (fun i l -> if i = n then f l else l)
    let private payload (f: JValue -> JValue) (l: JValue) = V110.setField "payload" (f (V110.field "payload" l |> Option.defaultValue JNull)) l
    let private indexOf (pred: JValue -> bool) (lines: JValue list) = lines |> List.findIndex pred
    let private isType t (l: JValue) = V110.strField "eventType" l = Some t
    let private creationRevision t (lines: JValue list) =
        lines |> List.indexed |> List.find (fun (i, l) -> isType t l && i > 0 && V110.strField "correlationId" lines[i - 1] = V110.strField "correlationId" l) |> fst

    let negatives (valid: InvestigationFiles) (lines: JValue list) : Result<Negative list, string> =
        let neg name description expected domain (files: Result<InvestigationFiles, string>) =
            files |> Result.map (fun f -> { Name = name; Description = description; Files = f; ExpectedErrorCode = expected; ExpectedDomainCode = domain })
        let evRev = creationRevision "EvidenceRevised" lines
        let obRev = creationRevision "ObservationRevised" lines
        let standaloneEv = lines |> List.indexed |> List.findBack (fun (i, l) -> isType "EvidenceRevised" l && i <> evRev && V110.strField "correlationId" lines[i - 1] <> V110.strField "correlationId" l) |> fst
        let supersededDraft = guid "evidence" "draft-capture"
        let relatedNew = indexOf (fun l -> isType "EvidenceRelated" l && V110.strField "kind" (V110.field "payload" l |> Option.defaultValue JNull) = Some "consistentWith") lines
        let noRevisions = lines |> List.filter (V110.isRevision >> not)
        [ neg "mixed-version-line" "One event line of a 1.1.0 investigation carries formatVersion 1.0.0: one investigation has one version." Codes.unsupportedVersion None
              (withLines valid (lines |> at 3 (V110.setField "formatVersion" (JStr "1.0.0"))))
          neg "mixed-version-manifest" "A 1.0.0 manifest over 1.1.0 events." Codes.unsupportedVersion None
              (parseDoc valid.Manifest |> Result.bind (fun m -> Json.fileBytes (m |> V110.setField "formatVersion" (JStr "1.0.0") |> V110.setField "schemaVersion" (JStr "1.0.0") |> V110.setField "semanticVersion" (JStr "1.0.0")))
               |> Result.map (fun mb -> { valid with Manifest = mb }))
          neg "unsupported-version-1-2-0" "Every version string is 1.2.0, which neither reader supports." Codes.unsupportedVersion None
              (allVersions "1.2.0" valid lines)
          neg "v100-evidence-revised" "A 1.0.0 history carrying EvidenceRevised: the type is not registered in 1.0.0." Codes.unknownEventType None
              (allVersions "1.0.0" valid lines)
          neg "v100-kind-consistent-with" "A 1.0.0 history whose relationship kind is consistentWith: outside the 1.0.0 enumeration." Codes.schemaViolation None
              (allVersions "1.0.0" valid noRevisions)
          neg "label-null" "EvidenceRevised.label is null: the label is required on the wire (S-7 A)." Codes.schemaViolation None
              (withLines valid (lines |> at evRev (payload (V110.setField "label" JNull))))
          neg "label-blank" "EvidenceRevised.label is whitespace only." Codes.schemaViolation None
              (withLines valid (lines |> at evRev (payload (V110.setField "label" (JStr " 　 ")))))
          neg "evidence-revised-unknown-field" "EvidenceRevised carries a field 1.1.0 does not define (closed structures)." Codes.schemaViolation None
              (withLines valid (lines |> at evRev (payload (V110.setField "category" (JStr "log")))))
          neg "source-url-javascript" "sourceUrl javascript:alert(1) is not an absolute http(s) URL (schema pattern)." Codes.schemaViolation None
              (withLines valid (lines |> at evRev (payload (V110.setField "sourceUrl" (JStr "javascript:alert(1)")))))
          neg "source-url-scheme-slash" "sourceUrl http:/x fails the schema pattern." Codes.schemaViolation None
              (withLines valid (lines |> at evRev (payload (V110.setField "sourceUrl" (JStr "http:/x")))))
          neg "source-url-not-well-formed" "sourceUrl 'https://a b' passes the pattern but is not a well-formed URL (stage 15)." Codes.historyInadmissible (Some "EVIDENCE.URL")
              (withLines valid (lines |> at evRev (payload (V110.setField "sourceUrl" (JStr "https://a b")))))
          neg "evidence-revision-mismatch" "In the admitting group, EvidenceRevised.source differs from EvidenceAdmitted.source (S-3 A)." Codes.historyInadmissible (Some "EVIDENCE.REVISION_MISMATCH")
              (withLines valid (lines |> at evRev (payload (V110.setField "source" (JStr "another source")))))
          neg "observation-revision-mismatch" "In the recording group, ObservationRevised.original differs from ObservationRecorded.original (S-3 A)." Codes.historyInadmissible (Some "OBSERVATION.REVISION_MISMATCH")
              (withLines valid (lines |> at obRev (payload (V110.setField "original" (JStr "The slowdown affects only card payments")))))
          neg "evidence-revised-missing" "EvidenceRevised names evidence that does not exist." Codes.historyInadmissible (Some "HISTORY.INADMISSIBLE_EVENT")
              (withLines valid (lines |> at standaloneEv (payload (V110.setField "evidenceId" (JStr(Uuid.text (guid "evidence" "missing")))))))
          neg "evidence-revised-superseded" "A standalone EvidenceRevised of superseded evidence, appended at the end." Codes.historyInadmissible (Some "EVIDENCE.SUPERSEDED")
              (let last = List.last lines
               let n = int64 lines.Length + 1L
               let corr = guid "command" "revise-superseded"
               let line =
                   lines[standaloneEv]
                   |> V110.setField "aggregateVersion" (JInt n) |> V110.setField "correlationId" (JStr(Uuid.text corr))
                   |> V110.setField "eventId" (JStr(Uuid.text (Uuid.eventId inv.Value n corr)))
                   |> V110.setField "occurredAt" (V110.field "occurredAt" last |> Option.defaultValue JNull)
                   |> payload (V110.setField "evidenceId" (JStr(Uuid.text supersededDraft)))
               withLines valid (lines @ [ line ]))
          neg "revision-group-time-differs" "The EvidenceRevised of an admitting group carries another occurredAt than its EvidenceAdmitted." Codes.historyInadmissible (Some "HISTORY.INADMISSIBLE_EVENT")
              (withLines valid (lines |> at evRev (V110.setField "occurredAt" (JStr "2026-11-06T23:59:59.000Z"))))
          neg "relationship-kind-unknown" "A relationship kind outside the 1.1.0 enumeration (no fallback value)." Codes.schemaViolation None
              (withLines valid (lines |> at relatedNew (payload (V110.setField "kind" (JStr "consistent-with"))))) ]
        |> traverse (fun x -> x)

    // ---------------- files on disk ----------------

    let root = "fixtures/v1.1.0"

    let private write (path: string) (bytes: byte[]) =
        Directory.CreateDirectory(Path.GetDirectoryName path |> nonNull) |> ignore
        File.WriteAllBytes(path, bytes)

    let private negativeJson (n: Negative) =
        let file (b: byte[]) = JObj [ "base64", JStr(Convert.ToBase64String b) ]
        JObj [ "formatVersion", JStr V110.version; "name", JStr n.Name; "description", JStr n.Description; "kind", JStr "investigation"
               "expectedErrorCode", JStr n.ExpectedErrorCode
               "expectedDomainCode", (match n.ExpectedDomainCode with Some d -> JStr d | None -> JNull)
               "directoryId", JStr n.Files.DirectoryId
               "files", JObj [ "events.ndjson", file n.Files.Events; "manifest.json", file n.Files.Manifest; "snapshot.json", file n.Files.Snapshot ] ]

    /// Every file of fixtures/v1.1.0 as (path relative to the repository, bytes).
    let build () : Result<(string * byte[]) list, string> =
        result {
            let! lines = valid ()
            let! files = V110.filesOf lines |> Result.mapError (fun e -> e.Code + ": " + e.Detail)
            let! negs = negatives files lines
            let dir = root + "/investigations/" + files.DirectoryId + "/"
            let! negFiles = negs |> traverse (fun n -> Json.fileBytes (negativeJson n) |> Result.map (fun b -> root + "/negative/" + n.Name + ".json", b))
            let index =
                JObj [ "formatVersion", JStr V110.version
                       "investigations", JArr [ JObj [ "investigationId", JStr files.DirectoryId; "scenarioKey", JStr scenarioKey ] ]
                       "negativeFixtures", JArr(negs |> List.map (fun n -> JObj [ "path", JStr("negative/" + n.Name + ".json"); "expectedErrorCode", JStr n.ExpectedErrorCode ])) ]
            let! indexBytes = Json.fileBytes index
            return [ dir + "manifest.json", files.Manifest; dir + "events.ndjson", files.Events; dir + "snapshot.json", files.Snapshot
                     root + "/index.json", indexBytes ] @ negFiles
        }

    /// Writes fixtures/v1.1.0 under `repo` (refusing to touch anything else).
    let generate (repo: string) =
        build () |> Result.map (fun files ->
            files |> List.iter (fun (p, b) -> write (Path.Combine(repo, p)) b)
            files.Length)

    /// Rebuilds in memory and compares with disk byte for byte; then verifies every fixture with the 1.1.0 reader.
    let verify (repo: string) (v100: SchemaCheck.SchemaSet) (v110: SchemaCheck.SchemaSet) : string list =
        match build () with
        | Error e -> [ "build: " + e ]
        | Ok files ->
            [ for (p, b) in files do
                  let full = Path.Combine(repo, p)
                  if not (File.Exists full) then yield p + ": missing (run v110-fixtures)"
                  elif File.ReadAllBytes full <> b then yield p + ": differs from the deterministic rebuild"
              let onDisk = Directory.GetFiles(Path.Combine(repo, root), "*", SearchOption.AllDirectories) |> Array.map (fun f -> Path.GetRelativePath(repo, f).Replace('\\', '/'))
              for f in onDisk do
                  if not (files |> List.exists (fst >> (=) f)) then yield f + ": not produced by the generator"
              match valid () |> Result.bind (V110.filesOf >> Result.mapError (fun e -> e.Detail)) with
              | Error e -> yield "valid: " + e
              | Ok f ->
                  match V110.validate v100 v110 f with
                  | Ok v when v.Format = V110.V110 -> ()
                  | Ok _ -> yield "valid: read as 1.0.0"
                  | Error e -> yield "valid: " + e.Code + " " + e.Detail
                  match valid () |> Result.bind (fun ls -> negatives f ls) with
                  | Error e -> yield "negatives: " + e
                  | Ok ns ->
                      for n in ns do
                          match V110.validate v100 v110 n.Files with
                          | Ok _ -> yield n.Name + ": accepted, expected " + n.ExpectedErrorCode
                          | Error e when e.Code <> n.ExpectedErrorCode || e.DomainCode <> n.ExpectedDomainCode ->
                              yield $"{n.Name}: {e.Code} {e.DomainCode} ({e.Detail}), expected {n.ExpectedErrorCode} {n.ExpectedDomainCode}"
                          | Error _ -> () ]
